package Assignment;

public class Assignment1 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		  // Using appropriate primitive data types
		        int employeeId = 1001;          // int for ID
		        byte age = 28;                  // byte is enough for age
		        double salary = 55000.50;       // double for salary with decimals
		        char department = 'T';          // char for single-letter department code
		        boolean isPermanent = true;     // boolean for permanent status

		        // Printing employee details
		        System.out.println("Employee ID: " + employeeId);
		        System.out.println("Age: " + age);
		        System.out.println("Salary: " + salary);
		        System.out.println("Department: " + department);
		        System.out.println("Permanent: " + isPermanent);
		    }
		}
